
-- Stark Packmate sales meeting redesign and pipeline correction.
-- Production was corrected before this repository migration was recorded.
alter table public.calendar_event_links drop constraint if exists calendar_event_links_entity_type_check;
alter table public.calendar_event_links add constraint calendar_event_links_entity_type_check check (entity_type = any (array['lead'::text,'inbound_lead'::text,'quote'::text,'order'::text,'task'::text,'mail_thread'::text,'trade_event'::text]));
with retired as (select l.id as lead_id,ps.name as old_stage from public.leads l join public.pipeline_stages ps on ps.id=l.stage_id where l.organization_id='b97913cb-3b95-4247-8ced-ffdc0d392d2a' and l.stage_id in ('c3481f5e-0721-4910-ac4e-f51992608b28','d869b9a1-8b49-4099-a3d4-1f3eda08896c'))
insert into public.lead_activities (organization_id,lead_id,actor_user_id,kind,message,occurred_at) select 'b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid,lead_id,null,'pipeline_stage_retired','Historical stage preserved during meeting workflow redesign: '||old_stage||'. Meetings are now tracked as sales activities rather than pipeline qualification stages.',now() from retired;
update public.leads set stage_id='4d03c65e-4b22-4ba7-ac70-164620f6852d',updated_at=now() where organization_id='b97913cb-3b95-4247-8ced-ffdc0d392d2a' and stage_id in ('c3481f5e-0721-4910-ac4e-f51992608b28','d869b9a1-8b49-4099-a3d4-1f3eda08896c');
delete from public.pipeline_stages where pipeline_id='128c037a-a669-473b-a884-ea668752e93c' and id in ('c3481f5e-0721-4910-ac4e-f51992608b28','d869b9a1-8b49-4099-a3d4-1f3eda08896c');
update public.pipeline_stages set sort_order=sort_order+100,updated_at=now() where pipeline_id='128c037a-a669-473b-a884-ea668752e93c';
update public.pipeline_stages set name=case id when '4d03c65e-4b22-4ba7-ac70-164620f6852d'::uuid then 'New Packaging Inquiry' when 'ec56d754-a4f8-4c2e-8f34-ac4105466011'::uuid then 'Quote Sent' when 'a89de723-f100-4274-8d77-92bb594888a1'::uuid then 'Sample Sent' when '0c5a1aed-684b-42cc-83bb-172f28dafae2'::uuid then 'Artwork Reviewed' when 'd24ce8f0-8577-4dde-a51a-988276a9f991'::uuid then 'Won' when '5e909a5e-0fe0-40cf-b267-450d7d3af206'::uuid then 'Lost' else name end,sort_order=case id when '4d03c65e-4b22-4ba7-ac70-164620f6852d'::uuid then 1 when 'ec56d754-a4f8-4c2e-8f34-ac4105466011'::uuid then 2 when 'a89de723-f100-4274-8d77-92bb594888a1'::uuid then 3 when '0c5a1aed-684b-42cc-83bb-172f28dafae2'::uuid then 4 when 'd24ce8f0-8577-4dde-a51a-988276a9f991'::uuid then 5 when '5e909a5e-0fe0-40cf-b267-450d7d3af206'::uuid then 6 else sort_order-100 end,updated_at=now() where pipeline_id='128c037a-a669-473b-a884-ea668752e93c';
